typedef struct GCB89_AnimationPreset {
    GC89_Fixed micro_scale_fx;
    GC89_Fixed neutral_scale_fx;
    GC89_Fixed maxi_scale_fx;
    GC89_Fixed speed_fx_per_tick;
} GCB89_AnimationPreset;


/* Declarative animation-event recipe ABI. Legacy AnimationPreset stays intact. */
#define GCB89_ANIM_EVENT_AIM_ENTER 0
#define GCB89_ANIM_EVENT_AIM_EXIT  1
#define GCB89_ANIM_EVENT_FIRE      2
#define GCB89_ANIM_EVENT_HIT       3
#define GCB89_ANIM_EVENT_DISABLED  4
#define GCB89_ANIM_EVENT_ENABLED   5
#define GCB89_ANIM_EVENT_CUSTOM1   6
#define GCB89_ANIM_EVENT_CUSTOM2   7
#define GCB89_ANIM_EVENT_COUNT     8

#define GCB89_ANIM_SCALE_NEUTRAL 0
#define GCB89_ANIM_SCALE_MICRO   1
#define GCB89_ANIM_SCALE_MAXI    2
#define GCB89_ANIM_SCALE_CUSTOM  3
#define GCB89_ANIM_SCALE_CURRENT 4

#define GCB89_ANIM_CURVE_LINEAR     0
#define GCB89_ANIM_CURVE_EASE_IN    1
#define GCB89_ANIM_CURVE_EASE_OUT   2
#define GCB89_ANIM_CURVE_SMOOTHSTEP 3
#define GCB89_ANIM_CURVE_SNAP       4

#define GCB89_ANIM_RETURN_NONE    0
#define GCB89_ANIM_RETURN_START   1
#define GCB89_ANIM_RETURN_NEUTRAL 2

#define GCB89_ANIM_RETRIGGER_RESTART 0
#define GCB89_ANIM_RETRIGGER_IGNORE  1

/* All multipliers are Q16.16. Rotation is degrees Q16.16, offsets are pixels Q16.16. */
typedef struct GCB89_AnimationEventRecipe {
    int enabled;
    int scale_target;
    GC89_Fixed scale_fx;
    GC89_Fixed rotation_deg_fx;
    GC89_Fixed offset_x_fx;
    GC89_Fixed offset_y_fx;
    GC89_Fixed alpha_fx;
    GC89_Fixed thickness_scale_fx;
    GC89_Fixed dot_scale_fx;
    unsigned long attack_ticks;
    unsigned long hold_ticks;
    unsigned long return_ticks;
    int attack_curve;
    int return_curve;
    int return_mode;
    int repeat_count;
    int retrigger_mode;
} GCB89_AnimationEventRecipe;

typedef struct GCB89_AnimationRecipe {
    int auto_input_events;
    GCB89_AnimationEventRecipe events[GCB89_ANIM_EVENT_COUNT];
} GCB89_AnimationRecipe;

